import{_ as i,o as u,c as n,a2 as t}from"./chunks/framework.CqpfiAoK.js";const z=JSON.parse('{"title":"Sheria ya Uhakikisho wa Elimu","description":"","frontmatter":{},"headers":[],"relativePath":"sw/43-教育保障法.md","filePath":"sw/43-教育保障法.md","lastUpdated":1789183869000}'),m={name:"sw/43-教育保障法.md"};function l(e,a,o,k,h,s){return u(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="sheria-ya-uhakikisho-wa-elimu" tabindex="-1">Sheria ya Uhakikisho wa Elimu <a class="header-anchor" href="#sheria-ya-uhakikisho-wa-elimu" aria-label="Permalink to &quot;Sheria ya Uhakikisho wa Elimu&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mradi</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya hati</td><td>43</td></tr><tr><td>Moduli</td><td>Mfumo wa Kisheria na Muundo wa Usimamizi</td></tr><tr><td>Maneno muhimu ya msingi</td><td>Haki ya Elimu, Elimu ya Usawa, Urithi wa Mazoezi, Elimu ya Maisha Yote, Haki ya Elimu</td></tr></tbody></table><h2 id="_1-lengo-la-kisheria-na-kanuni-za-msingi" tabindex="-1">1. Lengo la Kisheria na Kanuni za Msingi <a class="header-anchor" href="#_1-lengo-la-kisheria-na-kanuni-za-msingi" aria-label="Permalink to &quot;1. Lengo la Kisheria na Kanuni za Msingi&quot;">​</a></h2><p>《Sheria ya Uhakikisho wa Elimu》 ni moja ya sheria tano za msingi za ustaarabu wa usawa wa nanga, na lengo lake ni kuhakikisha haki ya elimu ya kila kiumbe ndani ya Hengyuanzhou, kujenga mfumo wa elimu wenye dhana kuu ya &quot;mageuzi ya usawa&quot;, na kutoa msaada wa maarifa na vtalenta kwa maendeleo ya pamoja ya kila kabila.</p><p>Sheria hii inaweka kanuni zifuatazo za msingi:</p><table tabindex="0"><thead><tr><th>Kanuni</th><th>Maudhui</th></tr></thead><tbody><tr><td>Kanuni ya Haki ya Elimu</td><td>Kila kiumbe, bila kujali kabila, kiwango cha mazoezi, asili, hufurahia nafasi za elimu sawa</td></tr><tr><td>Kanuni ya Kufundisha Kulingana na Talanta</td><td>Kuheshimu tofauti za talanta na uchaguzi wa njia ya mageuzi ya kila kiumbe, kutoa mipango ya elimu ya kibinafsi</td></tr><tr><td>Kanuni ya Umoja wa Maarifa na Tendo</td><td>Kuunganisha maarifa ya kinadharia na mazoezi ya vitendo, kupinga elimu ya mazungumzo matupu yasiyotegemea ukweli</td></tr><tr><td>Kanuni ya Ufumbuzi na Kushiriki</td><td>Rasilimali za elimu zinafumbuliwa kwa jamii nzima, mbinu za msingi za mifumo mia tatu ya mazoezi ya asili hufundishwa bure</td></tr><tr><td>Kanuni ya Elimu ya Maisha Yote</td><td>Elimu inapitia mchakato wote wa maisha, inasaidia kujifunza kwa kuendelea na kuboresha uwezo katika kila hatua</td></tr><tr><td>Kanuni ya Utamaduni wa Anuwai</td><td>Kuheshimu desturi za kitamaduni za kila kabila, kuchochea ubadilishaji na kujifunza kwa kina kati ya tamaduni</td></tr></tbody></table><h2 id="_2-uhakikisho-wa-kisheria-wa-haki-ya-elimu" tabindex="-1">2. Uhakikisho wa Kisheria wa Haki ya Elimu <a class="header-anchor" href="#_2-uhakikisho-wa-kisheria-wa-haki-ya-elimu" aria-label="Permalink to &quot;2. Uhakikisho wa Kisheria wa Haki ya Elimu&quot;">​</a></h2><p>Sheria hii inabainisha wazi kwamba haki ya elimu ni haki ya msingi inayotolewa kwa kila kiumbe na Katiba ya Usawa, na serikali na ustaarabu wana jukumu la kuhakikisha utekelezaji wa haki hii:</p><ol><li><strong>Elimu ya Msingi Bure</strong>: Kila kiumbe ana haki ya kupokea elimu ya msingi bure, ikiwa ni pamoja na maarifa ya jumla, mbinu za msingi za mazoezi, dhana za ustaarabu wa usawa, n.k., muda wa elimu ni miaka sita hadi kumi na mbili, na inarekebishwa kulingana na mzunguko wa ukuaji wa kabila.</li><li><strong>Utangulizi wa Mazoezi Bure</strong>: Mbinu za msingi za mifumo mia tatu ya mazoezi ya asili ya ulimwengu zinafumbuliwa bure kwa kila kiumbe, hakuna shirika au mtu binafsi anaweza kuchukua mbinu za msingi za mazoezi kama mali ya kibinafsi na kufundisha kwa malipo.</li><li><strong>Usawa wa Nafasi za Elimu ya Juu</strong>: Taasisi za elimu kwa kila kiwango na aina hazifai kuweka masharti ya ubaguzi kama vile kabila, kiwango cha mazoezi, asili, n.k. katika ukodi, na vigezo vya ukodi vinapaswa kuwa wazi na wazi.</li><li><strong>Uhakikisho wa Elimu Maalum</strong>: Kutoa rasilimali za elimu maalum zinazofaa na msaada wa elimu ya mbali kwa vikundi kama vile viumbe vilemavu, viumbe vya kabila nyingine, viumbe kutoka viwango vya kulejana, n.k.</li><li><strong>Mfumo wa Msaada wa Elimu</strong>: Kutoa fedha za elimu, tuzo za uwezo, na mikopo isiyo na riba kwa wanafunzi walio na ugumu wa kiuchumi, kuhakikisha hawapotezi nafasi ya elimu kwa sababu za kiuchumi.</li></ol><h2 id="_3-muundo-wa-mfumo-wa-elimu" tabindex="-1">3. Muundo wa Mfumo wa Elimu <a class="header-anchor" href="#_3-muundo-wa-mfumo-wa-elimu" aria-label="Permalink to &quot;3. Muundo wa Mfumo wa Elimu&quot;">​</a></h2><p>Mfumo wa elimu wa ustaarabu wa usawa wa nanga umegawanyika katika viwango vinne, ambavyo vinaunganishwa kwa kina kati yao:</p><table tabindex="0"><thead><tr><th>Kiwango</th><th>Jina</th><th>Lengo</th><th>Muda wa Elimu</th></tr></thead><tbody><tr><td>Kiwango cha kwanza</td><td>Elimu ya Awali</td><td>Kujenga uwezo wa kuzingatia msingi na ufahamu wa usawa, kufundisha mbinu za msingi za mazoezi</td><td>Miaka 3-6</td></tr><tr><td>Kiwango cha pili</td><td>Elimu ya Msingi</td><td>Kujifunza kwa utaratibu maarifa ya jumla na nadharia za mazoezi, kugundua mwelekeo wa talanta ya mtu binafsi</td><td>Miaka 6-9</td></tr><tr><td>Kiwango cha tatu</td><td>Elimu ya Kitaaluma</td><td>Kujifunza kwa kina na mazoezi katika mfumo wa mazoezi au uwanja wa kitaaluma uliochaguliwa</td><td>Miaka 3-10</td></tr><tr><td>Kiwango cha nne</td><td>Utafiti wa Juu</td><td>Uchunguzi wa mbele na utafiti wa ubunifu kwa wanaofanya mazoezi wa juu na watafiti</td><td>Haina kikomo</td></tr></tbody></table><p>Zaidi ya hayo, &quot;Mfumo wa Mtandao wa Walimu&quot; umeanzishwa: wanaofanya mazoezi waliofikia kiwango fulani cha mazoezi wana jukumu la kuongoza wanaofanya mazoezi wa awali ndani ya uwezo wao, na mchango wa mwongozo unahesabiwa katika kiwango cha mchango wa mfumo wa mkataba wa uzalishaji wa pamoja, na hufurahia usambazaji wa rasilimali unaolingana.</p><h2 id="_4-taasisi-za-elimu-na-walimu" tabindex="-1">4. Taasisi za Elimu na Walimu <a class="header-anchor" href="#_4-taasisi-za-elimu-na-walimu" aria-label="Permalink to &quot;4. Taasisi za Elimu na Walimu&quot;">​</a></h2><ul><li><strong>Taasisi za Elimu za Umma</strong>: Zimeanzishwa na serikali au jumuiya ya ustaarabu, zinabeba jukumu la elimu ya msingi bure na huduma za elimu za umma, na fedha zinahakikishwa na akiba ya umma.</li><li><strong>Taasisi za Elimu za Kibinafsi</strong>: Zimeanzishwa na nguvu za jamii kulingana na sheria, zinaweza kuchukua malipo yanayofaa, lakini lazima zakubali ushirikiano wa idara inayohusiana ya elimu, na hazifai kufanya tangazo la uongo au kuchukua malipo ya mauaji.</li><li><strong>Madhehebu ya Mazoezi</strong>: Mashirika ya jadi ya mazoezi baada ya usajili yanaweza kufanya shughuli kama taasisi za elimu ya kitaaluma, lazima zifuata masharti ya sheria ya elimu, na hazifai kufunga na kutumia monolopoli rasilimali za mazoezi.</li><li><strong>Haki na Wajibu wa Walimu</strong>: Walimu hufurahia haki kama vile uhuru wa kitaaluma, malipo yanayofaa, mafunzo ya kitaaluma, n.k., na wakati huo huo wana wajibu wa kufundisha na kuelimisha, kuwa mfano, kulinda faragha ya wanafunzi, n.k.</li></ul><h2 id="_5-maudhui-ya-elimu-na-viwango-vya-mafunzo" tabindex="-1">5. Maudhui ya Elimu na Viwango vya Mafunzo <a class="header-anchor" href="#_5-maudhui-ya-elimu-na-viwango-vya-mafunzo" aria-label="Permalink to &quot;5. Maudhui ya Elimu na Viwango vya Mafunzo&quot;">​</a></h2><p>Maudhui ya elimu yanapaswa kutimiza mahitaji yafuatayo:</p><ol><li>Inajumuisha dhana kuu ya ustaarabu wa usawa na elimu ya kupinga mauaji, na kujenga ufahamu wa usawa wa wanafunzi.</li><li>Inajumuisha nadharia ya msingi na mbinu za utangulizi za mifumo mia tatu ya mazoezi ya asili.</li><li>Inajumuisha maarifa ya kisayansi ya jumla kama vile sheria za ulimwengu, maarifa ya viwango, sayansi ya maisha, n.k.</li><li>Inajumuisha historia na utamaduni wa kila kabila, na kuchochea uelewa na heshima kwa kina kati ya makabila.</li><li>Inajumuisha sehemu ya mazoezi ya vitendo na huduma za jamii, na kujenga uwezo wa kuunganisha maarifa na tendo.</li><li>Inakataza kusambaza dhana za mazoezi ya mauaji na mawazo ya ubaguzi.</li></ol><h2 id="_6-wajibu-wa-kisheria" tabindex="-1">6. Wajibu wa Kisheria <a class="header-anchor" href="#_6-wajibu-wa-kisheria" aria-label="Permalink to &quot;6. Wajibu wa Kisheria&quot;">​</a></h2><p>Shughuli zinazovunja masharti ya sheria hii zitabeba wajibu ufuatao kulingana na ukubwa wa makosa:</p><ul><li>Kukataa au kuzuia kiumbe cha umri wa shule kupokea elimu ya lazima, kuamriwa kurekebisha na kupigwa faini.</li><li>Taasisi za elimu zinazochukua malipo ya kikatili au kufanya tangazo la uongo, kuamriwa kurejesha malipo na kupigwa faini, katika visa vizito leseni ya uendeshaji wa elimu inakatiwa.</li><li>Walimu wanaofanya adhabu ya mwili au ubaguzi kwa wanafunzi, wanapigwa faini, katika visa vizito uwezo wa mwalimu unakatiwa na wajibu wa kisheria unafuatiliwa.</li><li>Kuchukua rasilimali za mazoezi za umma kama mali ya kibinafsi, kutumia monolopoli na kuchukua malipo, mapato ya kikatili yanakamatwa na kupigwa faini.</li></ul><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>《Sheria ya Uhakikisho wa Elimu》 ni mazoezi ya elimu ya dhana ya &quot;kila mtu ana njia&quot; ya ustaarabu wa usawa wa nanga. Kupitia kuhakikisha haki ya elimu, kujenga mfumo wa elimu wa viwango, na kufungua rasilimali za mazoezi, inahakikisha kwamba kila kiumbe anaweza kupata njia ya mageuzi inayofaa kwa yeye mwenyewe, na kutoa maarifa na vtalenta kwa kila wakati kwa maendeleo ya pamoja ya kila kabila.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Kanuni za Msingi za Katiba ya Usawa)</li><li>37-共生教育体系 (Mfumo wa Elimu ya Usawa)</li><li>10-三百套本源修炼体系总览 (Muhtasari wa Mifumo Mia Tatu ya Mazoezi ya Asili)</li><li>08-人人有路保障体系 (Mfumo wa Uhakikisho wa Kila Mtu Ana Njia)</li></ul>',25)])])}const r=i(m,[["render",l]]);export{z as __pageData,r as default};
